import assert from 'node:assert/strict';
import test from 'node:test';
import { createPricingModel } from '../src/angular-pricing.mjs';

test('Angular signals drive and recompute pricing state', () => {
  const pricing = createPricingModel(4950, 2);
  assert.equal(pricing.priceCents(), 4950);
  assert.equal(pricing.quantity(), 2);
  assert.equal(pricing.totalCents(), 9900);
  pricing.setQuantity(3);
  assert.equal(pricing.totalCents(), 14850);
  assert.throws(() => pricing.setQuantity(0), /quantity/i);
  assert.equal(pricing.quantity(), 3);
});

